import java.util.*;

class Solution {
    public String alienOrder(String[] words) {
        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> indegree = new HashMap<>();
        for (String word : words) {
            for (char ch : word.toCharArray()) {
                adj.putIfAbsent(ch, new HashSet<>());
                indegree.putIfAbsent(ch, 0);
            }
        }

        for (int i = 0; i + 1 < words.length; i++) {
            String first = words[i];
            String second = words[i + 1];
            if (first.length() > second.length() && first.startsWith(second)) {
                return "";
            }
            int limit = Math.min(first.length(), second.length());
            for (int j = 0; j < limit; j++) {
                char from = first.charAt(j);
                char to = second.charAt(j);
                if (from != to) {
                    if (adj.get(from).add(to)) {
                        indegree.merge(to, 1, Integer::sum);
                    }
                    break;
                }
            }
        }

        Queue<Character> queue = new ArrayDeque<>();
        for (char ch : indegree.keySet()) {
            if (indegree.get(ch) == 0) {
                queue.offer(ch);
            }
        }

        StringBuilder order = new StringBuilder();
        while (!queue.isEmpty()) {
            char ch = queue.poll();
            order.append(ch);
            for (char next : adj.get(ch)) {
                indegree.merge(next, -1, Integer::sum);
                if (indegree.get(next) == 0) {
                    queue.offer(next);
                }
            }
        }
        return order.length() == indegree.size() ? order.toString() : "";
    }
}

import java.util.*;

class Solution {
    private final Map<Character, Set<Character>> graph = new HashMap<>();
    private final Map<Character, Integer> state = new HashMap<>();
    private final StringBuilder order = new StringBuilder();

    public String alienOrder(String[] words) {
        for (String word : words) {
            for (char ch : word.toCharArray()) {
                graph.putIfAbsent(ch, new HashSet<>());
                state.putIfAbsent(ch, 0);
            }
        }

        for (int i = 0; i + 1 < words.length; i++) {
            String first = words[i];
            String second = words[i + 1];
            if (first.length() > second.length() && first.startsWith(second)) {
                return "";
            }
            int limit = Math.min(first.length(), second.length());
            for (int j = 0; j < limit; j++) {
                char from = first.charAt(j);
                char to = second.charAt(j);
                if (from != to) {
                    graph.get(from).add(to);
                    break;
                }
            }
        }

        List<Character> nodes = new ArrayList<>(state.keySet());
        for (char node : nodes) {
            if (state.get(node) == 0 && !dfs(node)) {
                return "";
            }
        }
        return order.reverse().toString();
    }

    private boolean dfs(char node) {
        state.put(node, 1);
        for (char next : graph.get(node)) {
            int nextState = state.get(next);
            if (nextState == 1) {
                return false;
            }
            if (nextState == 0 && !dfs(next)) {
                return false;
            }
        }
        state.put(node, 2);
        order.append(node);
        return true;
    }
}

