class Solution {
    public String alienOrder(String[] words) {
        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> indegree = new HashMap<>();
        for (String word : words) {
            for (char ch : word.toCharArray()) {
                adj.putIfAbsent(ch, new HashSet<>());
                indegree.putIfAbsent(ch, 0);
            }
        }

        for (int i = 0; i + 1 < words.length; i++) {
            String first = words[i];
            String second = words[i + 1];
            if (first.length() > second.length() && first.startsWith(second)) {
                return "";
            }
            int limit = Math.min(first.length(), second.length());
            for (int j = 0; j < limit; j++) {
                char from = first.charAt(j);
                char to = second.charAt(j);
                if (from != to) {
                    if (adj.get(from).add(to)) {
                        indegree.merge(to, 1, Integer::sum);
                    }
                    break;
                }
            }
        }

        PriorityQueue<Character> ready = new PriorityQueue<>();
        for (char ch : indegree.keySet()) {
            if (indegree.get(ch) == 0) {
                ready.offer(ch);
            }
        }

        StringBuilder order = new StringBuilder();
        while (!ready.isEmpty()) {
            char ch = ready.poll();
            order.append(ch);
            for (char next : adj.get(ch)) {
                indegree.put(next, indegree.get(next) - 1);
                if (indegree.get(next) == 0) {
                    ready.offer(next);
                }
            }
        }
        return order.length() == indegree.size() ? order.toString() : "";
    }
}

import java.util.*;

class Solution {
    public String alienOrder(String[] words) {
        boolean[] present = new boolean[26];
        int[] firstSeen = new int[26];
        Arrays.fill(firstSeen, -1);
        List<Character> chars = new ArrayList<>();
        for (String word : words) {
            for (char ch : word.toCharArray()) {
                int id = ch - 'a';
                if (!present[id]) {
                    present[id] = true;
                    firstSeen[id] = chars.size();
                    chars.add(ch);
                }
            }
        }

        boolean[][] before = new boolean[26][26];
        for (int i = 0; i + 1 < words.length; i++) {
            String first = words[i];
            String second = words[i + 1];
            int limit = Math.min(first.length(), second.length());
            int j = 0;
            while (j < limit && first.charAt(j) == second.charAt(j)) {
                j++;
            }
            if (j == limit) {
                if (first.length() > second.length()) {
                    return "";
                }
            } else {
                before[first.charAt(j) - 'a'][second.charAt(j) - 'a'] = true;
            }
        }

        for (int k = 0; k < 26; k++) {
            for (int i = 0; i < 26; i++) {
                if (!before[i][k]) {
                    continue;
                }
                for (int j = 0; j < 26; j++) {
                    if (before[k][j]) {
                        before[i][j] = true;
                    }
                }
            }
        }

        for (int i = 0; i < 26; i++) {
            if (before[i][i]) {
                return "";
            }
        }

        chars.sort((left, right) -> {
            int leftPredecessors = predecessorCount(before, left - 'a');
            int rightPredecessors = predecessorCount(before, right - 'a');
            if (leftPredecessors != rightPredecessors) {
                return Integer.compare(leftPredecessors, rightPredecessors);
            }
            return Integer.compare(firstSeen[left - 'a'], firstSeen[right - 'a']);
        });

        StringBuilder order = new StringBuilder();
        for (char ch : chars) {
            order.append(ch);
        }
        return order.toString();
    }

    private static int predecessorCount(boolean[][] before, int node) {
        int count = 0;
        for (int i = 0; i < 26; i++) {
            if (before[i][node]) {
                count++;
            }
        }
        return count;
    }
}
